@push('scripts')<script>
$(function(){function dateDisplay(v){if(!v)return '—';const p=String(v).slice(0,10).split('-');return p.length===3?`${p[2]}-${p[1]}-${p[0]}`:v;}const detailModal=new bootstrap.Modal('#returnDetailModal');const table=$('#productionReceiptTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.warehouse-production-receipts.dt')),data:d=>{d.from_date=$('#from_date').val();d.to_date=$('#to_date').val()}},columns:[{data:'id',orderable:false,searchable:false,render:(d,t,r,m)=>m.row+m.settings._iDisplayStart+1},{data:'actions',orderable:false,searchable:false,className:'text-center'},{data:'approval_status',orderable:false,searchable:false},{data:'number',name:'number'},{data:'return_date',name:'return_date',render:dateDisplay},{data:'mo',orderable:false},{data:'approver_name',orderable:false},{data:'approved_at',name:'approved_at'}],order:[[4,'desc']],drawCallback:()=>window.feather&&feather.replace()});$('#filterReceipts').on('click',()=>table.ajax.reload());$('#exportProductionReceipt').on('click',function(e){e.preventDefault();const u=new URL(this.href);u.searchParams.set('from_date',$('#from_date').val());u.searchParams.set('to_date',$('#to_date').val());location.href=u});$(document).on('click','.btn-show-production-return',function(){const b=$(this);$.get(b.data('url')).done(d=>{$('#returnDetailTitle').text(`${@json(__('ui.production_return.receipt_title'))} · ${d.number}`);let rows=d.items.map((i,n)=>`<tr><td>${n+1}</td><td>${$('<div>').text(i.code||'—').html()}</td><td>${$('<div>').text(i.name||'—').html()}</td><td>${$('<div>').text(i.unit||'—').html()}</td><td>${$('<div>').text(i.style||'—').html()}</td><td class="text-end">${Number(i.quantity).toLocaleString()}</td><td>${$('<div>').text(i.description||'—').html()}</td></tr>`).join('');$('#returnDetailBody').html(`<p><strong>${@json(__('ui.production_return.mo'))}:</strong> ${$('<div>').text(d.mo).html()} &nbsp; <strong>${@json(__('ui.production_return.date'))}:</strong> ${dateDisplay(d.date)}</p><div class="table-responsive"><table class="table table-sm table-bordered"><thead><tr><th>No</th><th>${@json(__('ui.production_return.item_code'))}</th><th>${@json(__('ui.production_return.item_name'))}</th><th>${@json(__('ui.production_return.unit'))}</th><th>${@json(__('ui.production_return.style'))}</th><th>${@json(__('ui.production_return.quantity'))}</th><th>${@json(__('ui.production_return.description'))}</th></tr></thead><tbody>${rows}</tbody></table></div>`);detailModal.show()})});$(document).on('click','.btn-approve-production-return,.btn-cancel-production-return',function(){const b=$(this),cancel=b.hasClass('btn-cancel-production-return');Swal.fire({icon:'warning',title:cancel?@json(__('ui.production_return.cancel_title')):@json(__('ui.production_return.approve_title')),text:cancel?'':@json(__('ui.production_return.approve_help')),showCancelButton:true,confirmButtonText:cancel?@json(__('ui.common.cancel')):@json(__('ui.workflow.approve'))}).then(r=>{if(!r.isConfirmed)return;$.ajax({url:b.data('url'),method:'PUT',data:{_token:@json(csrf_token())}}).done(x=>{table.ajax.reload(null,false);Swal.fire({icon:'success',text:x.message})}).fail(x=>Swal.fire({icon:'error',text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'}))})})});
</script>@endpush
